# Each 8-component is tiled by 2x2 pieces. Full squares map to 1;
# the three demonstrated L orientations map to 2, 3, and 4.
PIECES = {
    frozenset({(0, 0), (0, 1), (1, 0), (1, 1)}): 1,
    frozenset({(0, 1), (1, 0), (1, 1)}): 2,
    frozenset({(0, 0), (0, 1), (1, 1)}): 3,
    frozenset({(0, 0), (1, 0), (1, 1)}): 4,
}


def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    placements = []
    by_cell = {p: [] for p in occupied}
    for mask, color in PIECES.items():
        for r in range(h):
            for c in range(w):
                cells = frozenset((r + dr, c + dc) for dr, dc in mask)
                if cells <= occupied:
                    placement = (cells, color)
                    placements.append(placement)
                    for p in cells:
                        by_cell[p].append(placement)

    def solve(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(cells <= remaining for cells, _ in by_cell[p]))
        for cells, color in by_cell[cell]:
            if cells <= remaining:
                rest = solve(remaining - cells)
                if rest is not None:
                    return [(cells, color)] + rest
        return None

    pieces = solve(occupied)
    if pieces is None:
        raise ValueError("input cannot be tiled by the demonstrated pieces")
    output = [[0 for _ in range(w)] for _ in range(h)]
    for cells, color in pieces:
        for r, c in cells:
            output[r][c] = color
    return output


if __name__ == "__main__":
    import sys
    import json
    print(json.dumps(transform(json.loads(sys.stdin.read()))))
